{
  "network": {
    "variables": {
      "F": {
        "states": ["present", "absent"],
        "parents": [],
        "cpt": [
          {"when": {}, "probabilities": {"present": 0.20, "absent": 0.80}}
        ]
      },
      "A": {
        "states": ["positive", "negative"],
        "parents": ["F"],
        "cpt": [
          {"when": {"F": "present"}, "probabilities": {"positive": 0.80, "negative": 0.20}},
          {"when": {"F": "absent"},  "probabilities": {"positive": 0.10, "negative": 0.90}}
        ]
      }
    }
  },
  "query": ["F"],
  "evidence": {"A": "positive"}
}
EOF
echo '--- engine ---'; $P analyze --engine discrete-bayes --data "$(cat .pearl/fault-alert-model.json)"; echo; echo '--- hand check + sensitivity ---'; python3 - <<'EOF'
def post(pf, tpr, fpr):
    num = pf*tpr; den = num + (1-pf)*fpr
    return num/den, den
p, pa = post(0.20, 0.80, 0.10)
print(f"base: P(F|A)={p:.6f}  P(A)={pa:.4f}  LR+={0.80/0.10:.1f}  prior odds={0.2/0.8:.3f} post odds={p/(1-p):.3f}")
print("sensitivity (one at a time):")
for pf in (0.05, 0.10, 0.20, 0.30, 0.50): print(f"  P(F)={pf:.2f} -> P(F|A)={post(pf,0.80,0.10)[0]:.3f}")
for tpr in (0.60, 0.80, 0.95): print(f"  P(A|F)={tpr:.2f} -> P(F|A)={post(0.20,tpr,0.10)[0]:.3f}")
for fpr in (0.02, 0.05, 0.10, 0.20): print(f"  P(A|~F)={fpr:.2f} -> P(F|A)={post(0.20,0.80,fpr)[0]:.3f}")
EOF

